-- statement
INSERT INTO square_uploads(upload_id) SELECT NULL WHERE NOT (EXISTS(SELECT 1 FROM profile_asset_uploads WHERE upload_id=json_extract(?1,'$.credential.upload_id') AND cid_number=json_extract(?1,'$.auth.cid_number') AND generation=json_extract(?1,'$.credential.generation') AND generation=(SELECT MAX(generation) FROM profile_asset_uploads WHERE cid_number=json_extract(?1,'$.auth.cid_number') AND kind=json_extract(?1,'$.credential.kind')) AND (state='writing' OR (state='completed' AND object_etag=json_extract(?1,'$.etag')))));
-- statement
UPDATE profile_asset_uploads SET state='completed',object_etag=json_extract(?1,'$.etag'),completed_at=COALESCE(completed_at,json_extract(?1,'$.auth.now')) WHERE upload_id=json_extract(?1,'$.credential.upload_id') AND cid_number=json_extract(?1,'$.auth.cid_number') AND generation=json_extract(?1,'$.credential.generation') AND generation=(SELECT MAX(generation) FROM profile_asset_uploads WHERE cid_number=json_extract(?1,'$.auth.cid_number') AND kind=json_extract(?1,'$.credential.kind')) AND state='writing';
